def _read_runtime_version_string() -> str:
    """Best-effort: read MonClub Access version from update.json / version.json.

    Used by the boot/shutdown banner so an incident log clearly shows which
    build is running. Falls back to "unknown" on any failure.
    """
    try:
        from shared.runtime_support import runtime_base_dir

        for filename, key in (("version.json", None), ("update.json", "access")):
            try:
                path = runtime_base_dir() / filename
                if not path.exists():
                    continue
                import json as _json
                data = _json.loads(path.read_text(encoding="utf-8-sig"))
                payload = data if key is None else (data.get(key) or {})
                version = str(payload.get("version") or "").strip()
                if version:
                    codename = str(payload.get("codename") or "").strip()
                    return f"{version} ({codename})" if codename else version
            except Exception:
                continue
    except Exception:
        pass
    return "unknown"


def _parse_dt_any(s: str) -> datetime | None:
    if not s:
        return None
    s = str(s).strip()
    if not s:
        return None
    if s.endswith("Z"):
        s = s[:-1]
    try:
        return datetime.fromisoformat(s)
    except Exception:
        pass
    try:
        if len(s) == 10 and s[4] == "-" and s[7] == "-":
            return datetime.fromisoformat(s + "T00:00:00")
    except Exception:
        pass
    return None


def _shadow_am_id(u: Any) -> int | None:
    """activeMembershipId of an incoming sync user as an int, parsed exactly like
    db.upsert_member_shadow / db.diff_member_shadow do (None when absent or
    non-numeric, so the write-set filter and the writer agree on every row)."""
    if not isinstance(u, dict):
        return None
    raw = u.get("activeMembershipId") or u.get("active_membership_id")
    if raw is None:
        return None
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


def _log_sync_cache_write_profile(logger: Any, elapsed_ms: int) -> None:
    if int(elapsed_ms or 0) < 250:
        return
    logger.info("[SYNC-DEBUG] local cache write took %dms", int(elapsed_ms or 0))
    try:
        from app.core.db import get_last_db_write_profile

        profile = get_last_db_write_profile("save_sync_cache_delta")
        if profile:
            logger.info("[SYNC-DEBUG] local cache write profile=%s", profile)
    except Exception:
        logger.debug("[SYNC-DEBUG] local cache write profile unavailable", exc_info=True)


def _should_defer_ultra_reconnects(trigger_source: str) -> bool:
    normalized = str(trigger_source or "").strip().upper()
    return normalized in {"CHANGE_DETECTOR", "FAST_PATCH_BUNDLE", "SYNC_NOW_API"}


def check_zkemkeeper_registration() -> Dict[str, Any]:
    """
    Returns a diagnostic dict about ZKEMKeeper COM registration.
    Works without pywin32 by reading registry; optionally tries COM activation if
    pywin32 or comtypes exists.
    """
    result: Dict[str, Any] = {
        "ok": False,
        "windows": (os.name == "nt"),
        "pythonBits": None,  # filled in below from struct.calcsize on Windows
        "progId": "zkemkeeper.CZKEM",
        "clsid": None,
        "inprocServer32": None,
        "inprocExists": None,
        "registryFound": False,
        "comCreateOk": None,
        "error": None,
        "notes": [],
    }

    if os.name != "nt":
        result["error"] = "Not Windows (COM registration applies on Windows only)."
        return result

    try:
        import struct
        result["pythonBits"] = struct.calcsize("P") * 8
    except Exception:
        result["pythonBits"] = None

    try:
        import winreg

        def _reg_get(path: str, value_name: str | None, wow: int | None) -> str | None:
            # wow: None = default, 32 = WOW6432Node view, 64 = 64-bit view
            access = winreg.KEY_READ
            if wow == 32:
                access |= getattr(winreg, "KEY_WOW64_32KEY", 0)
            elif wow == 64:
                access |= getattr(winreg, "KEY_WOW64_64KEY", 0)

            try:
                with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT, path, 0, access) as k:
                    name = value_name if value_name is not None else ""
                    v, _t = winreg.QueryValueEx(k, name)
                    return str(v) if v is not None else None
            except FileNotFoundError:
                return None
            except OSError:
                return None

        # Try both registry views because many ZKTeco components are 32-bit COM
        views = [None, 32, 64]
        progid_paths = [
            r"zkemkeeper.CZKEM\CLSID",
            r"zkemkeeper.CZKEM.1\CLSID",
        ]

        clsid = None
        clsid_view = None
        for wow in views:
            for p in progid_paths:
                v = _reg_get(p, None, wow)
                if v and v.strip().startswith("{") and v.strip().endswith("}"):
                    clsid = v.strip()
                    clsid_view = wow
                    break
            if clsid:
                break

        if not clsid:
            result["error"] = "ProgID not found in registry (zkemkeeper.CZKEM)."
            return result

        result["registryFound"] = True
        result["clsid"] = clsid
        result["notes"].append(f"ProgID->CLSID found (view={clsid_view}).")

        inproc = None
        inproc_view = None
        for wow in views:
            v = _reg_get(rf"CLSID\{clsid}\InprocServer32", None, wow)
            if v and v.strip():
                inproc = v.strip()
                inproc_view = wow
                break

        result["inprocServer32"] = inproc
        if inproc:
            result["notes"].append(f"InprocServer32 found (view={inproc_view}).")
            try:
                result["inprocExists"] = Path(inproc).exists()
            except Exception:
                result["inprocExists"] = None
        else:
            result["notes"].append("InprocServer32 not found for CLSID (COM may be broken).")

        # REAL COM activation test.
        #
        # This must never be faked. The previous version called
        # zkemkeeper_scanner.create_zkemkeeper_com_object(), which is a stub that
        # returns (None, "powershell") and can never raise -- so the except branch
        # was unreachable and comCreateOk/ok were set True unconditionally. The app
        # therefore reported a healthy COM registration on machines where none
        # existed. A diagnostic that always says "fine" is worse than none at all,
        # because it is exactly what an on-site technician trusts.
        #
        # We Dispatch the same ProgIDs the ZK_STANDALONE driver tries, in the same
        # order (app/sdk/zk_standalone.py). NOTE: the driver uses DispatchWithEvents,
        # which additionally needs the type library and a working event sink. We
        # deliberately do NOT do that here -- it is heavier and this runs on the
        # startup thread -- so a green probe proves the class is registered and
        # loadable, NOT that event delivery works. That limit is stated in notes
        # rather than implied by a green flag.
        try:
            import pythoncom  # type: ignore
            import win32com.client as w32  # type: ignore
        except Exception as exc:
            result["comCreateOk"] = None  # untested, NOT "passed"
            result["notes"].append(f"pywin32 unavailable; COM activation not tested ({exc}).")
        else:
            co_initialised = False
            activation_error: Any = None
            try:
                try:
                    pythoncom.CoInitialize()
                    co_initialised = True
                except Exception:
                    # Already initialised on this thread is fine; anything else will
                    # surface as a Dispatch failure below.
                    pass

                obj = None
                for prog_id in ("zkemkeeper.ZKEM", "zkemkeeper.CZKEM", "zkemkeeper.ZKEM.1"):
                    try:
                        obj = w32.Dispatch(prog_id)
                        result["notes"].append(f"COM activation succeeded via {prog_id}.")
                        break
                    except Exception as exc:
                        activation_error = exc

                result["comCreateOk"] = obj is not None
                if obj is None:
                    result["error"] = f"COM activation failed: {activation_error}"
                    # zkemkeeper is a 32-bit in-process COM server. A 64-bit process
                    # cannot load it in-process and gets "Class not registered" even
                    # when registration is perfectly good -- which is what a 64-bit
                    # dev run sees. The SHIPPED app is always 32-bit (enforced in
                    # build_release.ps1), so say this rather than let a developer
                    # conclude the client PC is broken.
                    if result.get("pythonBits") == 64:
                        result["notes"].append(
                            "Host process is 64-bit; zkemkeeper is a 32-bit in-process server, "
                            "so activation cannot succeed here regardless of registration. "
                            "The shipped app is 32-bit -- judge registration from that build."
                        )
                obj = None  # release the interface promptly
            finally:
                if co_initialised:
                    try:
                        pythoncom.CoUninitialize()
                    except Exception:
                        pass
            result["notes"].append(
                "Event-sink activation (DispatchWithEvents) is exercised only at device "
                "connect time and is NOT proven by this probe."
            )

        # 'ok' = the class is registered AND its server file exists AND, where we
        # could test it, the object actually activates. comCreateOk is None when
        # pywin32 is missing, which must not be treated as a pass or as a failure.
        result["ok"] = bool(
            result["registryFound"]
            and result.get("inprocExists")
            and result["comCreateOk"] is not False
        )
        return result

    except Exception as e:
        result["error"] = f"Registry check failed: {e}"
        return result


def _encoding_to_backend(enc: str) -> str:
    e = (enc or "").strip().lower()
    return "HEX" if e == "hex" else "BASE64"


