        self._tauri_process: Optional[Any] = None
        self._change_detector: Optional[ChangeDetectorService] = None
        self._log_sync_poller: Optional[LogSyncRequestPoller] = None

        self._offline_queue_lock = threading.Lock()
        self._offline_retry_interval_sec = 3600
        self._last_offline_retry_epoch = 0.0
        self._last_sync_online = False
        # Lifecycle-mutation queue (edit/renew/freeze/balance/delete/taxes on synced members).
        self._offline_mutation_lock = threading.Lock()
        self._last_mutation_retry_epoch = 0.0
        # HARD GATE: offline MONEY mutations (renew/balance/pay/markPaid) stay queued but are
        # NOT attempted until the backend idempotency layer is deployed — else a retry
        # double-charges. Flip to True only after that backend change ships.
        self._offline_money_mutations_enabled = False
        # H-005: Real sync telemetry for /status endpoint
        self._last_sync_at: Optional[str] = None
        self._last_sync_ok: bool = False
        self._last_sync_error: Optional[str] = None
        self._last_device_sync_at: Optional[str] = None
        self._last_device_sync_ok: bool = True
        self._last_device_sync_error: Optional[str] = None
        # Scheduled daily 22:00 auto-sync — outcome of the latest run (reported to backend).
        self._last_daily_sync_at: Optional[str] = None
        self._last_daily_sync_ok: Optional[bool] = None
        self._last_daily_sync_error: Optional[str] = None
        self._daily_sync_after_id: Optional[int] = None
        self._daily_sync_last_run_date: Optional[str] = None  # local YYYY-MM-DD of last fired run
        self._daily_sync_hour: int = 22  # 22:00 local
        self._feedback_event_seq: int = 0
