    def _reactive_token_refresh(self) -> Optional[str]:
        """Reactively rotate the access token using the stored refresh token after a 401.

        Used by the ChangeDetector (and any background poller) when the backend
        rejects the current JWT. Forces a refresh regardless of the proactive
        deadline and returns the new access token, or None when the session is
        truly gone or the refresh failed transiently (the caller should back off
        and retry, not hard-stop). Never raises.
        """
        try:
            auth = load_auth_token()
            if not auth or not auth.email:
                return None
            api = self._api()
            if api.do_proactive_refresh(email=auth.email, force=True):
                reloaded = load_auth_token()
                if reloaded and reloaded.token:
                    return reloaded.token
            return None
        except Exception as exc:
            self.logger.debug("[Auth] reactive token refresh failed: %s", exc)
            return None

    def _start_change_detector(self) -> None:
        """Lazily create and start ChangeDetectorService once logged in."""
        if self._change_detector is not None and self._change_detector._thread and self._change_detector._thread.is_alive():
            return
        try:
            from app.core.db import load_sync_access_software_settings
            from app.core.app_const import MONCLUB_BASE_URL
            settings = load_sync_access_software_settings()
            gym_id = settings.get("gymId") if settings else None
            if not gym_id:
                self.logger.debug("[ChangeDetector] No gymId in settings, skipping start")
                return
            self._change_detector = ChangeDetectorService(
                app=self,
                backend_base_url=MONCLUB_BASE_URL,
                get_token_fn=lambda: (load_auth_token().token if load_auth_token() else ""),
                re_login_fn=self._reactive_token_refresh,
                gym_id=int(gym_id),
                logger=self.logger,
            )
            self._change_detector.start()
            # Start the log-sync-request poller alongside. It checks every
            # 10 min whether the dashboard has queued a "flush my logs now"
            # request (the slow path of the F1 design — used when the
            # dashboard couldn't reach the local API directly).
            try:
                if self._log_upload_queue is not None and self._log_sync_poller is None:
                    self._log_sync_poller = LogSyncRequestPoller(
                        backend_base_url=MONCLUB_BASE_URL,
                        get_token_fn=lambda: (load_auth_token().token if load_auth_token() else ""),
                        flush_fn=self._log_upload_queue.flush_now,
                        logger=self.logger,
                    )
                    self._log_sync_poller.start()
            except Exception as poll_exc:
                self.logger.warning("[LogSyncPoller] Failed to start: %s", poll_exc)
        except Exception as exc:
            self.logger.warning("[ChangeDetector] Failed to start: %s", exc)

    def _start_daily_sync_scheduler(self) -> None:
        """Start the once-per-day 22:00-local auto-sync watchdog (idempotent).

        Uses a lightweight ~1-minute self-rescheduling check rather than a single 24h timer, so it
        survives clock drift / sleep and still fires if the PC was off at exactly 22:00 but came
        back a few minutes later. The fired sync is a FORCED full reconcile (reason=daily-auto-sync)
        that pushes even in manual sync mode; its outcome is reported to the backend so the
        dashboard can show a "daily sync failed" notification.
        """
        if self._daily_sync_after_id is not None:
            return  # already armed
        self._daily_sync_check()

    def _daily_sync_check(self) -> None:
        try:
            from datetime import datetime

            now = datetime.now()  # local time (gym PC clock)
            today = now.date().isoformat()
            if now.hour >= self._daily_sync_hour and self._daily_sync_last_run_date != today:
                self._daily_sync_last_run_date = today
                self.logger.info(
                    "[DailySync] Firing scheduled daily auto-sync (>= %02d:00 local)",
                    self._daily_sync_hour,
                )
                self.request_sync_now(
                    trigger_source="SYNC_NOW_API",
                    run_type="TRIGGERED",
                    trigger_hint={"reason": "daily-auto-sync"},
                )
        except Exception:
            self.logger.warning("[DailySync] check failed", exc_info=True)
        finally:
            # Re-arm the check ~every minute.
            try:
                self._daily_sync_after_id = self.after(60 * 1000, self._daily_sync_check)
            except Exception:
                self._daily_sync_after_id = None

